yy,xx=np.mgrid[:480,:848];z=d; pc=np.stack([(xx-424)*z/376.7245,(yy-240)*z/376.7245,z,np.ones_like(z)],-1); w=(Ti@pc.reshape(-1,4).T).T[:,:3].reshape(480,848,3)
roi=np.zeros(d.shape,bool);roi[200:310,280:500]=1
for cond,name in [((np.max(im,axis=2)-np.min(im,axis=2)<3)&(im[:,:,0]>45)&(im[:,:,0]<190),'gray'),((im[:,:,0]>140)&(im[:,:,0]<190)&(np.abs(im[:,:,0].astype(int)-im[:,:,1].astype(int))<5),'light')]:
 mask=roi&cond&(d>.3)&(d<1.5); pts=w[mask];print(name,len(pts));
 if len(pts):
  for filt, nm in [(pts,'all'),(pts[pts[:,2]>.84],'high')]:
   if len(filt): print(nm,'bounds',filt.min(0),filt.max(0),'med',np.median(filt,0),'pca',np.linalg.eigh(np.cov(filt[:,:2].T)))
